<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/include/clinical.php';hms_start_session();hms_require_role('patient');$ready=hms_stage6_ready($con);$rows=$ready?hms_db_query($con,'SELECT l.test_name,l.status,l.requested_at,d.doctorName,r.result_value,r.units,r.reference_range,r.remarks,r.completed_at FROM laboratory_requests l JOIN doctors d ON d.id=l.doctor_id LEFT JOIN laboratory_results r ON r.laboratory_request_id=l.id WHERE l.patient_user_id=? ORDER BY l.id DESC',[(int)$_SESSION['id']]):null;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My laboratory results · MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="vendor/fontawesome/css/font-awesome.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/themes/theme-1.css"><link rel="stylesheet" href="assets/css/medtech-app.css"></head><body><div id="app"><?php include 'include/sidebar.php';?><div class="app-content"><?php include 'include/header.php';?><main class="main-content"><div class="wrap-content container"><section id="page-title"><h1 class="mainTitle">Laboratory results</h1><p class="text-muted">Track the status and results of your requested tests.</p></section><section class="medtech-report-panel"><?php if(!$ready):?><div class="alert alert-warning"><?=hms_h(hms_clinical_notice())?></div><?php elseif($rows->num_rows):?><div class="table-responsive"><table class="table"><thead><tr><th>Test</th><th>Doctor</th><th>Status</th><th>Result</th><th>Reference range</th><th>Remarks</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=hms_h($r['test_name'])?></td><td><?=hms_h($r['doctorName'])?></td><td><span class="mt-status <?=hms_h($r['status'])?>"><?=hms_h(ucfirst($r['status']))?></span></td><td><?=hms_h($r['result_value']?($r['result_value'].' '.$r['units']):'Not completed')?></td><td><?=hms_h($r['reference_range'])?></td><td><?=hms_h($r['remarks'])?></td></tr><?php endwhile;?></tbody></table></div><?php else:?><div class="medtech-empty-state"><i class="fa fa-flask"></i><strong>No laboratory requests yet</strong><span>Your results will appear here after a doctor requests a test.</span></div><?php endif;?></section></div></main><?php include 'include/footer.php';?></div></div></body></html>
